_MIRA_REVISION = "932caadcee65242e439921ff37d99fb1906f7aad"

_MIRA_REFERENCE_CASES = [
    pytest.param(
        {},
        [436.620483, 414.743347, 446.626587],
        id="full-context",
    ),
    pytest.param(
        {"context_length": 36, "time_alpha": 0.5},
        [429.188873, 408.004120, 441.231659],
        id="context36-alpha05",
    ),
]


pytestmark = pytest.mark.skipif(
    not run_test_for_class(MIRAForecaster),
    reason="run test only if MIRAForecaster soft dependencies are present",
)


@pytest.mark.parametrize("forecaster_kwargs,expected_head", _MIRA_REFERENCE_CASES)
def test_mira_airline_predictions_match_source_reference(
    forecaster_kwargs, expected_head
):
    """MIRA predictions for airline match the reference inference loop."""
    y = load_airline()
    fh = np.arange(1, 4)

    forecaster = MIRAForecaster(
        model_path="MIRA-Mode/MIRA",
        revision=_MIRA_REVISION,
        **forecaster_kwargs,
    )

    y_pred = forecaster.fit(y, fh=fh).predict(fh=fh)

    np.testing.assert_allclose(
        y_pred.to_numpy().ravel(),
        np.asarray(expected_head, dtype=np.float32),
        rtol=1e-5,
        atol=1e-4,
    )
